import{_ as e,o,c as d,a2 as s}from"./chunks/framework.CNDaxUod.js";const m=JSON.parse('{"title":"Roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),a={name:"guide/roles.md"};function r(n,t,i,h,c,l){return o(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><p>Everything in AsyncUp asks for one <strong>permission</strong>: the web app, the <a href="./api.html">JSON API</a>, Chat commands and <a href="./mcp.html">MCP</a> tools. A <strong>role</strong> is a named set of permissions. A person holds a role either <strong>across the workspace</strong> or <strong>on one standup</strong>. Their access is everything their roles give them, added together.</p><h2 id="where-access-comes-from" tabindex="-1">Where access comes from <a class="header-anchor" href="#where-access-comes-from" aria-label="Permalink to &quot;Where access comes from&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>What the person gets</th><th>Where it applies</th></tr></thead><tbody><tr><td>Google Workspace admin (through the <a href="./directory.html">Directory</a>), or the SAML admin group</td><td>Admin</td><td>The workspace</td></tr><tr><td>The operator token (<code>OPERATOR_TOKEN</code>), while token sign-in is on</td><td>Admin</td><td>The workspace</td></tr><tr><td>On a standup&#39;s roster</td><td>Member</td><td>That standup</td></tr><tr><td>A standup&#39;s admin: ran <code>setup</code>, created it, <code>admin @user</code>, or made a manager on the Team page</td><td>Manager</td><td>That standup</td></tr><tr><td>A grant, by email</td><td>The granted role, built-in or custom</td><td>The workspace, or one standup</td></tr></tbody></table><h2 id="built-in-roles" tabindex="-1">Built-in roles <a class="header-anchor" href="#built-in-roles" aria-label="Permalink to &quot;Built-in roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>For</th><th>Granted?</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td>Running the install: every standup, workspace settings, sign-in, tokens and roles</td><td>Across the workspace only</td></tr><tr><td><strong>Manager</strong></td><td>Running standups: settings, people, schedules and blockers</td><td>Across the workspace or on one standup</td></tr><tr><td><strong>Viewer</strong></td><td>Stakeholders who read but change nothing: answers, blockers, reports, the team, CSV export</td><td>Across the workspace or on one standup</td></tr><tr><td><strong>Member</strong></td><td>Answering: everyone on a roster has it on that standup</td><td>No, it comes from the roster</td></tr></tbody></table><p>Built-in roles can&#39;t be changed. Copy one to start a custom role.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Lets you</th><th>Admin</th><th>Manager</th><th>Viewer</th><th>Member</th></tr></thead><tbody><tr><td><code>standups.view</code></td><td>See a standup, who is on it and how today is going</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>answers.view</code></td><td>Read each day&#39;s answers</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>moods.comments</code></td><td>Read why people chose their mood, without names where moods are anonymous</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>blockers.view</code></td><td>See blockers and their updates</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>reports.view</code></td><td>See run history and insights</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>people.view</code></td><td>See the Team directory</td><td>✓</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>export</code></td><td>Download answers as CSV</td><td>✓</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>standups.configure</code></td><td>Change the schedule, questions, mood, escalation and webhook; run now, nudge, close polls</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>standups.archive</code></td><td>Archive a standup and bring it back</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>people.manage</code></td><td>Add and remove people, mark them required, make managers, grant roles on the standup</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>schedules.manage</code></td><td>Change people&#39;s days and days off on the standup, decide time-off requests</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>blockers.manage</code></td><td>Resolve anyone&#39;s blocker</td><td>✓</td><td>✓</td><td></td><td></td></tr><tr><td><code>standups.create</code></td><td>Create standups</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>standups.delete</code></td><td>Delete an archived standup with its history</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>settings.manage</code></td><td>Workspace settings, setup checks, deleting history</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>sso.manage</code></td><td>Google sign-in, SAML and token sign-in</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>tokens.manage</code></td><td>Machine tokens, service MCP tokens, everyone&#39;s MCP tokens</td><td>✓</td><td></td><td></td><td></td></tr><tr><td><code>roles.manage</code></td><td>Create roles, grant them across the workspace, and set the SAML admin group</td><td>✓</td><td></td><td></td><td></td></tr></tbody></table><p>The last six are <strong>workspace-only</strong>: they mean nothing on a single standup. Some things don&#39;t need a permission. People always answer, skip and manage their own days off (within the time-off policy), the owner and tagged people work a blocker, and anonymous moods stay anonymous for every role. Mood never appears in the Chat space, and everyone sees their own mood comment.</p><h2 id="custom-roles" tabindex="-1">Custom roles <a class="header-anchor" href="#custom-roles" aria-label="Permalink to &quot;Custom roles&quot;">​</a></h2><p>A custom role is a name, a description and any set of the permissions above. Good uses:</p><ul><li><strong>Auditor:</strong> <code>answers.view</code>, <code>reports.view</code> and <code>export</code>, across the workspace, for someone who reviews but never runs a standup.</li><li><strong>Coach:</strong> <code>schedules.manage</code> and <code>blockers.manage</code> on one standup, for a scrum master who isn&#39;t its manager.</li><li><strong>Help desk:</strong> <code>tokens.manage</code> and <code>sso.manage</code>, for IT without the rest of Admin.</li></ul><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Why</th></tr></thead><tbody><tr><td>You can only put permissions you hold into a role, and only grant or revoke a role whose permissions you hold at that scope</td><td>Nobody can hand themselves or others more than they have</td></tr><tr><td>Granting across the workspace needs <code>roles.manage</code>. On one standup, <code>people.manage</code> there is enough</td><td>Managers can bring in a Viewer for their own standup</td></tr><tr><td>A role with a workspace-only permission can only be granted across the workspace</td><td>Those permissions have no meaning on one standup</td></tr><tr><td>A custom role with any standup permission also gets <code>standups.view</code></td><td>The others work on a standup the holder can see</td></tr><tr><td>You can&#39;t revoke or edit away your own <code>roles.manage</code></td><td>Someone else, or the operator token, has to. Admins through Google or SAML are never locked out</td></tr><tr><td>A role that anyone holds can&#39;t be deleted</td><td>Revoke its grants first</td></tr></tbody></table><p>Grants follow a person&#39;s <strong>email</strong>. Google and SAML sign-ins carry it. In Chat it&#39;s the email AsyncUp has learned for that person, from the <a href="./directory.html">Directory</a> or their first message to the app. Changes apply on the person&#39;s next request.</p><h2 id="managing-roles" tabindex="-1">Managing roles <a class="header-anchor" href="#managing-roles" aria-label="Permalink to &quot;Managing roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>What you can do</th></tr></thead><tbody><tr><td>Web app: <strong>Settings › Roles</strong></td><td>See every role, its permissions and who holds it. Copy a role, build one from the permission checklist, edit or delete custom roles</td></tr><tr><td>Web app: <strong>Settings › Access</strong></td><td>See every grant and filter it by role. Grant a role across the workspace or on one standup, revoke, and read the change history</td></tr><tr><td>Web app: a standup&#39;s <strong>Settings › Roles on this standup</strong></td><td>Its managers grant and revoke roles on that standup</td></tr><tr><td>Chat: <code>role @user &lt;role&gt;</code></td><td>Grant a role on the space&#39;s standup. <code>role @user remove &lt;role&gt;</code> revokes it, and <code>roles</code> lists who holds what there. An email works in place of the mention</td></tr><tr><td><a href="./api.html#roles-and-grants">JSON API</a></td><td><code>/permissions</code>, <code>/roles</code>, <code>/grants</code> and <code>/roles/audit</code></td></tr></tbody></table><p>Every change to a role or grant is logged with who made it and when.</p><p><code>admin @user</code> in Chat, and <strong>Make manager</strong> on the Team page, still make someone one of the standup&#39;s admins. That gives them Manager there, and <code>status</code> lists them as its admins. Use a grant for access without being named as an admin.</p><h2 id="what-each-person-sees" tabindex="-1">What each person sees <a class="header-anchor" href="#what-each-person-sees" aria-label="Permalink to &quot;What each person sees&quot;">​</a></h2><ul><li><strong>Web app.</strong> Navigation, settings sections, standup tabs and every button follow the person&#39;s permissions. A Viewer gets Standups, Blockers, Reports and Team, with no Run now, roster or settings controls. Members get their own page at <code>/app/me</code>.</li><li><strong>Chat.</strong> Commands that change a standup need the permission in the <a href="./commands.html">command reference</a>. <code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, polls, <code>export</code> and <code>help</code> are open to everyone in the space.</li><li><strong>MCP.</strong> A personal token acts as its owner with their current roles. It&#39;s only offered the tools those roles could use somewhere, and each call is checked again for the standup it names.</li><li><strong>API.</strong> Each route in the OpenAPI document names its permission in <code>x-permission</code>. <code>GET /api/v1/me</code> lists the caller&#39;s permissions across the workspace and per standup.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>A standup always keeps at least one admin; removing the last is refused.</li><li>A standup created with no admins (for example from a script with the operator token) is open to configuration by anyone in its space. Name an admin when creating on someone&#39;s behalf.</li><li>Who may mark someone away is set per standup by its <a href="./schedules.html#who-can-change-what-the-time-off-policy">time-off policy</a>.</li><li>In the web app, creating a standup goes through the setup walkthrough, so it needs <code>settings.manage</code> as well as <code>standups.create</code>. The API needs only <code>standups.create</code>.</li></ul>',24)])])}const g=e(a,[["render",r]]);export{m as __pageData,g as default};
